import type { ComponentProps } from "react";

/**
 * 디자인 시스템 아이콘 세트 — Figma `Icon` 섹션(309:1900)의 심볼 SVG 를 그대로 인라인했습니다.
 *
 * lucide-react 로 "비슷한 모양"을 끌어다 쓰지 않고, 시안 벡터를 직접 관리합니다
 * (디자인 시스템 아이콘은 채움(fill) 기반이라 선(stroke) 기반인 lucide 와 형태가 다릅니다).
 *
 * 사용 규칙
 * - 색: `currentColor` 를 따릅니다 → 부모의 `text-*` 토큰으로 지정하세요.
 * - 크기: 기본 24x24(width/height 속성). 호출측에서 `size-*` 유틸리티로 덮어씁니다.
 *   `className` 에 크기 클래스를 기본값으로 넣지 않습니다 — Button 등이 쓰는
 *   `[&_svg:not([class*='size-'])]:size-5` 규칙이 동작해야 하기 때문입니다.
 * - 접근성: 기본 `aria-hidden`. 아이콘만 있는 버튼은 부모에 `aria-label` 을 주세요.
 *
 * Google/Kakao 브랜드 로고는 규정색을 쓰므로 `brand-icons.tsx` 에 따로 있습니다(여기서 재수출).
 */

type IconProps = ComponentProps<"svg">;

/** 모든 아이콘이 공유하는 24x24 프레임 */
function IconBase({ className, children, ...props }: IconProps) {
  return (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      focusable="false"
      className={className}
      {...props}
    >
      {children}
    </svg>
  );
}

